// Cross-implementation parity for the Glyph Composer: the same recipe must
// produce the same nodes here as it does in desktop GlyphViz, and a template
// saved by one app must be the file the other reads.
//
// The fixture is generated by tools/dump_glyph_recipes.py, which runs the REAL
// desktop `generate_nodes` and `recipe_to_dict`. Everything the Composer dialog
// does — on both sides — ends in those two calls, so this covers the whole of
// what the two apps have to agree about; the widgets above it are each app's
// own business.
//
// hyperglyph.parity.test.ts also diffs `generate_nodes`, but only over recipes
// the GENERATOR can produce (Angular and Linear, a narrow slice of the ranges).
// The Composer hands the entire LevelSpec to the user, so the cases here are
// deliberately the ones that harness cannot reach: Circular / Grid / Random
// placement, ragged grids, solid vs gradient colour (different code paths, one
// truncating and one rounding half-to-even), a count of 1, and four levels of
// nesting. See the dump tool's docstring for the full list.

import { describe, expect, it } from 'vitest'
import { generateNodes, recipeFromJson, recipeToJson } from './glyphRecipe'
import type { GvNode } from './types'
import fixtureRaw from './fixtures/glyph_recipes.json?raw'

interface FixtureNode {
  id: number
  type: number
  parent_id: number
  branch_level: number
  translate_x: number
  translate_y: number
  translate_z: number
  rotate_x: number
  rotate_y: number
  rotate_z: number
  scale_x: number
  scale_y: number
  scale_z: number
  color_r: number
  color_g: number
  color_b: number
  color_a: number
  geometry: number
  hide: number
  topo: number
  ratio: number
  rotation_mode: number
  topo_scale: number
}

interface FixtureCase {
  name: string
  recipe: unknown
  start_id: number
  parent_id: number
  base_branch_level: number
  /** False for a recipe whose placement is random on BOTH sides. */
  compare_positions: boolean
  nodes: FixtureNode[]
}

const fixture = JSON.parse(fixtureRaw) as { cases: FixtureCase[] }

/** Floats are compared at 1e-9; integer columns must match exactly. */
const TOL = 1e-9

function checkNode(actual: GvNode, expected: FixtureNode, where: string): void {
  expect(actual.id, `${where} id`).toBe(expected.id)
  expect(actual.type, `${where} type`).toBe(expected.type)
  expect(actual.parentId, `${where} parent_id`).toBe(expected.parent_id)
  expect(actual.branchLevel, `${where} branch_level`).toBe(expected.branch_level)
  expect(actual.geometry, `${where} geometry`).toBe(expected.geometry)
  expect(actual.hide, `${where} hide`).toBe(expected.hide)
  expect(actual.topo, `${where} topo`).toBe(expected.topo)
  expect(actual.rotationMode, `${where} rotation_mode`).toBe(expected.rotation_mode)

  // Colours are integers on both sides — an exact match, which is what makes
  // the half-to-even gradient rounding and the truncating solid path provable.
  expect(actual.color.r, `${where} color_r`).toBe(expected.color_r)
  expect(actual.color.g, `${where} color_g`).toBe(expected.color_g)
  expect(actual.color.b, `${where} color_b`).toBe(expected.color_b)
  expect(actual.color.a, `${where} color_a`).toBe(expected.color_a)

  expect(actual.rotate.x, `${where} rotate_x`).toBeCloseTo(expected.rotate_x, 9)
  expect(actual.rotate.y, `${where} rotate_y`).toBeCloseTo(expected.rotate_y, 9)
  expect(actual.rotate.z, `${where} rotate_z`).toBeCloseTo(expected.rotate_z, 9)
  expect(actual.scale.x, `${where} scale_x`).toBeCloseTo(expected.scale_x, 9)
  expect(actual.scale.y, `${where} scale_y`).toBeCloseTo(expected.scale_y, 9)
  expect(actual.scale.z, `${where} scale_z`).toBeCloseTo(expected.scale_z, 9)
  expect(Math.abs(actual.ratio - expected.ratio), `${where} ratio`).toBeLessThan(TOL)
  // The Topology Scale the level was generated at — the auto-fit's whole
  // output, and the one column here that no widget lets a user type on either
  // side while Auto is on.
  expect(Math.abs(actual.topoScale - expected.topo_scale), `${where} topo_scale`).toBeLessThan(TOL)
}

describe('glyph recipe parity with desktop generate_nodes', () => {
  it('has cases to check', () => {
    expect(fixture.cases.length).toBeGreaterThan(10)
  })

  for (const testCase of fixture.cases) {
    it(`matches the desktop for ${testCase.name}`, () => {
      const recipe = recipeFromJson(testCase.recipe)
      const nodes = generateNodes(recipe, {
        startId: testCase.start_id,
        parentId: testCase.parent_id,
        baseBranchLevel: testCase.base_branch_level,
      })

      expect(nodes.length, 'node count').toBe(testCase.nodes.length)
      nodes.forEach((node, i) => {
        checkNode(node, testCase.nodes[i], `${testCase.name}[${i}]`)
        if (testCase.compare_positions) {
          const expected = testCase.nodes[i]
          expect(node.translate.x, `${testCase.name}[${i}] translate_x`).toBeCloseTo(
            expected.translate_x,
            9,
          )
          expect(node.translate.y, `${testCase.name}[${i}] translate_y`).toBeCloseTo(
            expected.translate_y,
            9,
          )
          expect(node.translate.z, `${testCase.name}[${i}] translate_z`).toBeCloseTo(
            expected.translate_z,
            9,
          )
        }
      })
    })

    it(`round-trips the ${testCase.name} template through the desktop's JSON`, () => {
      // recipe_to_dict → recipeFromJson → recipeToJson must land back on the
      // desktop's own dict. That is what makes a .json template portable, which
      // is the only route a design takes between the two apps.
      expect(recipeToJson(recipeFromJson(testCase.recipe))).toEqual(testCase.recipe)
    })
  }
})
